public class MathSuite {
    // 1. Overloaded area calculation
    public static double area(double radius) {
        if (radius < 0) return 0.0;
        return Math.PI * radius * radius;
    }

    public static double area(double length, double width) {
        if (length < 0 || width < 0) return 0.0;
        return length * width;
    }

    // 2. Prime testing with square-root optimization
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    // 3. Recursive Greatest Common Divisor (Euclid's Algorithm)
    public static int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    public static void main(String[] args) {
        System.out.println("Circle Area (r=3.0): " + area(3.0));
        System.out.println("Rect Area (4x5): " + area(4.0, 5.0));
        System.out.println("Is 17 Prime: " + isPrime(17));
        System.out.println("GCD(48, 18): " + gcd(48, 18));
    }
}

