public class Main {
    public static double volume(double s) {
        return s * s * s;
    }

    public static double volume(double l, double w, double h) {
        return l * w * h;
    }

    public static double volume(double r, double h, boolean isCylinder) {
        return Math.PI * r * r * h;
    }

    public static void main(String[] args) {
        System.out.println("Cube: " + volume(3.0));
        System.out.println("Box: " + volume(2.0, 4.0, 5.0));
        double cyl = volume(3.0, 10.0, true);
        System.out.println("Cylinder: " + String.format("%.2f", cyl));
    }
}

