practiceProblems.solutionCode:
public class Main {
    public static int reverseNumber(int n, int rev) {
        if (n == 0) return rev;
        return reverseNumber(n / 10, rev * 10 + n % 10);
    }

    public static boolean isPalindrome(int n) {
        return n == reverseNumber(n, 0);
    }

    public static void main(String[] args) {
        System.out.println("12321 Palindrome: " + isPalindrome(12321));
        System.out.println("12345 Palindrome: " + isPalindrome(12345));
    }
}

