public class Main {
    public static int clamp(int val, int min, int max) {
        if (val < min) return min;
        if (val > max) return max;
        return val;
    }

    public static int quadraticRootsCount(double a, double b, double c) {
        double disc = b * b - 4 * a * c;
        if (disc > 0) return 2;
        if (disc == 0) return 1;
        return 0;
    }

    public static int power(int b, int e) {
        if (e == 0) return 1;
        return b * power(b, e - 1);
    }

    public static void main(String[] args) {
        System.out.println("Clamped 120: " + clamp(120, 0, 100));
        System.out.println("Roots for (1, -5, 6): " + quadraticRootsCount(1, -5, 6));
        System.out.println("3^3: " + power(3, 3));
    }
}
